const output = [];

for (const item of items) {
  let contactJid = null;

  const remoteJid = item.json.body.data.key.remoteJid;
  const senderPn = item.json.body.data.key.senderPn; // Pode estar ausente
  // const senderLid = item.json.body.data.key.senderLid; // Não vamos usar diretamente para o JID do contato

  // Prioriza o remoteJid se ele já for o JID canônico do contato/grupo
  if (remoteJid && (remoteJid.endsWith('@s.whatsapp.net') || remoteJid.endsWith('@g.us'))) {
    contactJid = remoteJid;
  }
  // Se remoteJid for um @lid E senderPn existir e for um JID canônico
  else if (remoteJid && remoteJid.endsWith('@lid') && senderPn && senderPn.endsWith('@s.whatsapp.net')) {
    contactJid = senderPn;
  }
  // Caso fallback (se a lógica acima não pegar, o que é menos comum mas bom prevenir)
  else {
    // Se senderPn for um JID canônico, usa ele
    if (senderPn && (senderPn.endsWith('@s.whatsapp.net') || senderPn.endsWith('@g.us'))) {
        contactJid = senderPn;
    } else {
        // Se nenhuma das opções acima funcionou, usa o remoteJid como último recurso,
        // mesmo que seja um @lid. Isso pode exigir investigação se acontecer.
        console.warn("Evolution API: JID canônico do contato não encontrado. Usando remoteJid de fallback.", remoteJid);
        contactJid = remoteJid;
    }
  }

  // Adiciona o JID extraído ao JSON do item para uso posterior
  item.json.extractedContactJid = contactJid;

  output.push(item);
}
return output;

