const arr = $json.image || [];
const MIME_DEFAULT = 'image/jpeg'; // mude para image/png se for o caso
const PREFIX_RE = /^data:.*;base64,/; // remove "data:image/...;base64," se existir

// Função para gerar nomes imagem01, imagem02...
const pad = n => String(n).padStart(2, '0');

const out = [];

arr.forEach((b64, i) => {
  out.push({
    json: {
      fileName: `imagem${pad(i + 1)}.jpg`,
      mimeType: MIME_DEFAULT,
      base64: String(b64).replace(PREFIX_RE, '')
    }
  });
});

return out;
